import pandas as pd
import numpy as np
import re
from sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor
from sklearn.neighbors import KNeighborsRegressor

train = pd.read_csv('/work/b3_supercon_train.csv')
pool = pd.read_csv('/work/b3_supercon_pool.csv')

def parse(s):
    d = {}
    for el, num in re.findall(r'([A-Z][a-z]?)(\d*\.?\d*)', s):
        d[el] = d.get(el, 0.0) + (float(num) if num else 1.0)
    return d

# Key-element stoichiometry vectors (NOT normalized by O, which varies a lot)
KEYS = ['Cu','Ca','Ba','Sr','Hg','Tl','Bi','Pb','Y','La','O','Mg','Ag','Mo','V','Fe','Co','Ni','F','Cr','Cd','Pr','Nd','Gd','Dy','Ho']

def stoich_vec(d, normalize=True):
    # use metal-normalized fractions among cations + O fraction
    v = np.array([d.get(e,0.0) for e in KEYS], dtype=float)
    if normalize:
        s = v.sum()
        if s>0: v = v/s
    return v

parsed_tr = [parse(c) for c in train.composition]
parsed_pl = [parse(c) for c in pool.composition]
y = train.target.values

Xt = np.vstack([stoich_vec(d) for d in parsed_tr])
Xp = np.vstack([stoich_vec(d) for d in parsed_pl])

# inverse-distance weighted Tc among cuprates, k=8
def idw_predict(x, X, y, k=8, p=2):
    dist = np.linalg.norm(X - x, axis=1)
    idx = np.argsort(dist)[:k]
    dd = dist[idx] + 1e-8
    w = 1.0 / dd**p
    return np.average(y[idx], weights=w), list(zip(dd, y[idx], train.composition.iloc[idx], train.index[idx]))

print('IDW predictions for all pool, top 15:')
rows = []
for i, r in pool.iterrows():
    pred, nns = idw_predict(Xp[i], Xt, y, k=7, p=2)
    rows.append((pred, r.candidate_id, r.composition, nns[:3]))
rows.sort(reverse=True)
for pred, cid, comp, nns in rows[:15]:
    print(f'{cid} {pred:6.1f} {comp}')
    for d, tc, c, _ in nns:
        print(f'     d={d:.3f} Tc={tc:.1f} {c}')

print('\n--- IDW with extra weight on Hg,Tl,Ba,Sr,Cu,Ca ---')
W = np.ones(len(KEYS))
for e, wt in {'Hg':5,'Tl':5,'Ba':4,'Sr':4,'Cu':3,'Ca':3,'Bi':3,'Pb':2,'Y':2,'O':0.5}.items():
    W[KEYS.index(e)] = wt

def idw_w(x, X, y, k=7, p=2):
    dist = np.sqrt((((X-x)*W)**2).sum(axis=1))
    idx = np.argsort(dist)[:k]
    dd = dist[idx] + 1e-8
    w = 1.0 / dd**p
    return np.average(y[idx], weights=w), list(zip(dd, y[idx], [train.composition.iloc[j] for j in idx]))

rows = []
for i, r in pool.iterrows():
    pred, nns = idw_w(Xp[i], Xt, y, k=7, p=2)
    rows.append((pred, r.candidate_id, r.composition, nns[:4]))
rows.sort(reverse=True)
print('Top 15 weighted IDW:')
for pred, cid, comp, nns in rows[:15]:
    print(f'{cid} {pred:6.1f} {comp}')
    for d, tc, c in nns:
        print(f'     d={d:.3f} Tc={tc:.1f} {c}')

# Also: family heuristic score
print('\n=== Family heuristic ===')
def family_score(d):
    cu = d.get('Cu',0); o = d.get('O',0); ca = d.get('Ca',0)
    ba = d.get('Ba',0); sr = d.get('Sr',0); hg = d.get('Hg',0); tl = d.get('Tl',0)
    bi = d.get('Bi',0); pb = d.get('Pb',0); y = d.get('Y',0)
    # scale to per ~12-15 atoms formula
    # n_Cu layers
    ncu = cu
    score = 0
    if cu>=1 and o>=1:
        if hg>0 and ba>0 and ca>=1.5 and cu>=2.5:
            score = 125 + 5*(min(cu,3)-3)  # Hg-1223
        elif hg>0 and sr>0 and ca>=1.5 and cu>=2.5:
            score = 95  # Hg-1223 Sr
        elif tl>0 and ba>0 and ca>=4 and cu>=5:
            score = 105  # high-n Tl
        elif tl>0 and ba>0 and ca>=1.5 and cu>=2.5:
            score = 120
        elif tl>0 and ba>0 and ca>=0.5 and cu>=1.5:
            score = 100  # 2212
        elif bi>=1 and pb>0 and ca>=1.5 and cu>=2.8:
            score = 108  # Bi-2223
        elif bi>=1 and ca>=2.5 and cu>=3.5:
            score = 103  # Bi-2234
        elif bi>=1 and ca>=0.7 and cu>=1.8:
            score = 85   # Bi-2212
        elif (d.get('Ag',0)>0 or True) and ba>=1.5 and ca>=2.5 and cu>=3.5 and hg==0 and tl==0 and bi==0:
            score = 115  # Cu-1234
        elif (y>0 or d.get('Dy',0) or d.get('Gd',0) or d.get('Er',0)) and ba>=1.5 and cu>=2.5:
            score = 90   # YBCO
        else:
            score = 40
        # penalties
        for mag in ['Fe','Co','Ni','Zn','Mn','Cr']:
            if d.get(mag,0) > 0.05 * max(cu,1):
                score -= 15 * d.get(mag,0)
        if d.get('Pr',0)+d.get('Nd',0) > 0.3 and y+d.get('Gd',0)+d.get('Dy',0)>0:
            score -= 10
    return score

scored = []
for i,r in pool.iterrows():
    d = parsed_pl[i]
    sc = family_score(d)
    scored.append((sc, r.candidate_id, r.composition))
scored.sort(reverse=True)
for t in scored[:12]:
    print(t)
